enable_drop_protection.compliant:
resource "google_spanner_database" "c1" {
  instance             = google_spanner_instance.c1.name
  name                 = "c1"
  enable_drop_protection = true
}

enable_drop_protection.non-compliant:
resource "google_spanner_database" "nc1" {
  instance             = google_spanner_instance.nc1.name
  name                 = "nc1"
  enable_drop_protection = false
}
